-5a3a-43f2-8e86-82d98220c562", "type": "concept", "title": "procedural text"}, {"id": "11ce8dbd-9199-4355-90fb-b10c2bc7ae45", "type": "concept", "title": "argument text"}, {"id": "7c26d82c-4db9-4c78-a5c4-de40d63964b7", "type": "concept", "title": "question-and-answer format"}, {"id": "8462753b-7b28-41be-b394-4368c0054e8f", "type": "concept", "title": "field guide"}, {"id": "2bd16d9c-8fca-465f-bf15-bfd867f70eca", "type": "concept", "title": "photo essay"}], "description": "Students learn to identify nonfiction structures so children can read for knowledge, curiosity, and critique."}, {"id": "a98bff14-7c72-40b2-965d-ca3b12258b9e", "type": "subtopic", "title": "Text Features and Visual Information", "children": [{"id": "ce31debb-9a1b-4c0a-b7ba-2dca92aef6f8", "type": "concept", "title": "heading"}, {"id": "28fc1cc6-7828-4b91-907e-8e4a57473212", "type": "concept", "title": "caption"}, {"id": "42fdec48-b5da-4da5-904d-f692af6d8477", "type": "concept", "title": "glossary"}, {"id": "a40f3b0b-e2d7-4f37-8ce8-93f05e75c949", "type": "concept", "title": "index"}, {"id": "72f5d1dc-3ff3-4bd9-bcc4-f3fd45a0d87e", "type": "concept", "title": "diagram"}, {"id": "e9ba1178-278d-45d4-924b-4db0c11d583e", "type": "concept", "title": "map"}, {"id": "d5cf16bb-452c-4e3a-bfa2-13860faa423e", "type": "concept", "title": "timeline"}, {"id": "7451b463-413e-49dc-94d7-7e7fafad624e", "type": "concept", "title": "infographic"}, {"id": "2bea40bc-a863-49e8-8917-0a118f601416", "type": "concept", "title": "sidebar"}, {"id": "72eec739-16f0-4e9d-9e09-3b8aba3f4668", "type": "concept", "title": "data visualization"}], "description": "Children need explicit support reading diagrams, captions, maps, timelines, tables, and other knowledge-building features."}, {"id": "4efa99b9-e4dd-4c57-a0c2-3cf862cdd237", "type": "subtopic", "title": "Accuracy, Inquiry, and Source Use", "children": [{"id": "4e737e23-1062-43e3-8ce9-284d729e929d", "type": "concept", "title": "source note"}, {"id": "d946b964-e52e-421a-9c49-f1fd8947