ce"}, {"id": "d22f55f7-6171-4bab-81a6-761f57190b96", "type": "concept", "title": "onomatopoeia"}, {"id": "5bcbe552-4c19-449a-8c7d-3ccb3cf25b92", "type": "concept", "title": "wordplay"}], "description": "Poetry makes language audible and memorable, strengthening children's phonological awareness and love of words."}, {"id": "d39fa6ed-d932-48b9-9435-d3bbe4a27345", "type": "subtopic", "title": "Poetic Forms for Children", "children": [{"id": "1452a0b5-51e5-4690-98c5-33ba14df53b5", "type": "concept", "title": "nursery rhyme"}, {"id": "81309da3-a773-483b-a0ae-36e4e834465d", "type": "concept", "title": "lullaby"}, {"id": "18b75989-7195-4939-987d-f87a8b231e6c", "type": "concept", "title": "haiku"}, {"id": "99e6cc89-fdeb-41df-8d56-a2655d796155", "type": "concept", "title": "free verse"}, {"id": "f6093617-0086-4fad-a7f3-6fe9a0748290", "type": "concept", "title": "list poem"}, {"id": "68c56baa-fa5d-495b-9db8-0614975675e7", "type": "concept", "title": "concrete poem"}, {"id": "9ea4a6b9-df55-421c-9042-d20f92a8f5f9", "type": "concept", "title": "narrative poem"}, {"id": "e4b992aa-61db-4570-b7a9-2a4e3a188032", "type": "concept", "title": "verse novel"}, {"id": "e84c6200-c98c-4f5e-84ef-688ef0adc3a8", "type": "concept", "title": "spoken word"}], "description": "Students sample many forms so poetry becomes a daily practice rather than a once-a-year unit."}, {"id": "3a991629-0136-4f03-9154-602511b666a2", "type": "subtopic", "title": "Performance and Classroom Practice", "children": [{"id": "7f390415-34b4-488d-aeab-236b2894fdd6", "type": "concept", "title": "choral reading"}, {"id": "12b5b5dc-d187-4f90-b646-5ef477a4b2c6", "type": "concept", "title": "echo reading"}, {"id": "bc84c77f-98c0-4580-b9de-f279c73c1563", "type": "concept", "title": "poetry theater"}, {"id": "761f8ed5-fc9a-4d8d-ad5d-d148eb2ff2ee", "type": "concept", "title": "recitation"}, {"id": "0534805e-2804-4ed3-8695-348a6c5bf2a2", "type": "concept", "title": "prosody"}, {"id": "ab4deb70-0a3e-4b4b-9869-3f9849e7c57e", "type"