lity"}, {"id": "ccce5cff-b893-468c-a72b-887202fcb2ec", "type": "concept", "title": "cultural specificity"}], "description": "Students learn to evaluate whether books offer complex, respectful, and specific portrayals rather than flattened representation."}, {"id": "e5263895-ef3a-4c61-b834-bbb76dca9360", "type": "subtopic", "title": "Inclusive Collections", "children": [{"id": "194f260c-a2e7-4c20-a861-d0c9f3fd0277", "type": "concept", "title": "multicultural literature"}, {"id": "e0b9d1a3-25f8-4aa2-a9f6-e04e22aeeaac", "type": "concept", "title": "bilingual books"}, {"id": "44a84b78-7504-44fb-948e-eab8ed4f063a", "type": "concept", "title": "translated books"}, {"id": "317a56ff-9681-4647-853f-62fee0d464e0", "type": "concept", "title": "Indigenous literature"}, {"id": "766a0df7-b8f6-4549-a15d-77f4ac4bbedc", "type": "concept", "title": "disability representation"}, {"id": "11930f10-fd4e-4cd1-81c6-523306d17d62", "type": "concept", "title": "LGBTQ+ representation"}, {"id": "a53e29f6-c8c8-48a7-8f26-9d6d2cd477dd", "type": "concept", "title": "religious diversity"}, {"id": "6fbf10d8-d1c5-410a-82ae-7c42d0c6ab27", "type": "concept", "title": "rural/urban representation"}, {"id": "bda89d38-ec3b-4996-8d36-1de59dd80fc8", "type": "concept", "title": "class representation"}], "description": "Inclusive children's literature includes race, culture, language, religion, disability, neurodiversity, gender, family structure, class, and geography."}, {"id": "82a03bc0-7ac9-4f5f-b534-6b1f2dd75b0f", "type": "subtopic", "title": "Critical and Anti-Bias Reading", "children": [{"id": "d9a62fa8-e9ac-46a5-9944-f1d50dff2b5f", "type": "concept", "title": "critical literacy"}, {"id": "fe8eec3d-d481-46ce-9377-5e2f68e72870", "type": "concept", "title": "anti-bias education"}, {"id": "808ddf99-1043-42d4-b8ca-7db3788895a2", "type": "concept", "title": "power analysis"}, {"id": "9a784d53-a05c-440a-bb75-257913a2579c", "type": "concept", "title": "voice"}, {"id": "3023e1af-99c7-4785-8b85-c3e31f06d319", "typ